    c.beginPath(); c.moveTo(-r, -r * 0.55); c.lineTo(-r * 0.85, -r * 0.85); c.lineTo(r * 0.85, -r * 0.85); c.lineTo(r, -r * 0.55); c.closePath();
    paintBody(c, col, -r * 0.85, -r * 0.55, { light: 0.5, dark: -0.1, glow: 10 });
