    c.fillStyle = 'rgba(255,255,255,0.8)';
    c.fillRect(r * 0.0, -r * 0.12, r * 0.45, r * 0.07); c.fillRect(r * 0.0, r * 0.02, r * 0.32, r * 0.07);
