    c.beginPath(); c.moveTo(0, r * 0.3); c.lineTo(0, r * 0.88); c.moveTo(-r * 0.35, r * 0.9); c.lineTo(r * 0.35, r * 0.9); c.stroke();
    c.save(); c.rotate(-0.25);
