    c.beginPath(); c.moveTo(-r * 0.98, -r * 0.3); c.lineTo(-r * 0.85, -r * 0.62); c.lineTo(r * 0.85, -r * 0.62); c.lineTo(r * 0.98, -r * 0.3); c.closePath();
    paintBody(c, col, -r * 0.62, -r * 0.3, { light: 0.5, dark: -0.2, glow: 18 });
