    c.beginPath(); c.moveTo(0, -r * 0.95); c.lineTo(r * 0.75, -r * 0.05); c.lineTo(0, r * 0.85); c.lineTo(-r * 0.75, -r * 0.05); c.closePath();
    paintBody(c, col, -r * 0.95, r * 0.85, { light: 0.5, dark: -0.6, glow: 22 });
